INSERT INTO relationship_type (relationship_type, category, is_symmetric, description) VALUES
('PersonOf', 'Divine', false, 'Subject is one of the three persons of the one God (the object).'),
('ManifestationOf', 'Divine', false, 'Subject is a manifestation (appearance, voice, sign or state) of the object.'),
('IdentifiedWith', 'Divine', false, 'Subject manifestation is identified with the object node; interpretation records whether the text states it or tradition reads it so.')
INSERT INTO divine (divine_id, display_name, divine_type, also_known_as, testament, appears_in_both_testaments, summary, summary_source, first_reference, verse_count, source_record_id) VALUES
('god_1324', 'God', 'Godhead', 'the LORD; JEHOVAH; the Almighty; the Most High; the Ancient of days', 'Old Testament', true, 'The one God of Israel, creator of heaven and earth, revealed in three persons: the Father, the Son and the Holy Spirit. Theographic tags every verse that names God, the LORD, JEHOVAH, the Almighty or the Father to this record without distinguishing the persons, so those verse mentions attach here.', 'Curated', 'Genesis 1:1', 8587, 'god_1324'),
('god_the_father', 'God the Father', 'DivinePerson', 'the Father; Abba', 'New Testament', true, 'First person of the Trinity. Speaks from heaven at Jesus'' baptism and transfiguration, sends the Son and the Spirit, and is addressed by Jesus as ''Abba, Father''. Old Testament mentions of God are attached to God rather than to the Father, because the text does not distinguish the persons.', 'Curated', 'Matthew 3:17', 0, NULL),
('god_the_son', 'God the Son', 'DivinePerson', 'the Word; the Son; Christ', 'New Testament', true, 'Second person of the Trinity: the eternal Word, who ''was with God, and was God'', became flesh as Jesus of Nazareth, rose, ascended and reigns. His earthly life, relationships and verse mentions are on the Person ''Jesus of Nazareth''; this node ties together all his manifestations.', 'Curated', 'John 1:1', 0, NULL),
('holy_spirit_7400', 'Holy Spirit', 'DivinePerson', 'Holy Ghost; the Spirit of God; the Comforter', 'Old Testament', true, 'Third person of the Trinity. Moves upon the waters at creation, comes upon judges, kings and prophets, overshadows Mary, descends on Jesus at his baptism, and is poured out at Pentecost as the Comforter Jesus promised.', 'Curated', 'Genesis 1:2', 246, 'holy_spirit_7400');
INSERT INTO manifestation (manifestation_id, display_name, manifestation_of, manifestation_kind, also_known_as, testament, appears_in_both_testaments, summary, summary_source, first_reference, passages, verse_count) VALUES
('word_in_the_beginning', 'The Word in the beginning', 'god_the_son', 'Pre-existence', NULL, 'New Testament', false, 'The Word who was in the beginning with God and was God, through whom all things were made.', 'Curated', 'John 1:1', 'John 1:1-3', 3),
('christ_as_angel_of_the_lord', 'Christ as the Angel of the Lord', 'god_the_son', 'Pre-incarnate appearance', NULL, 'Old Testament', false, 'The Angel of the Lord, who speaks as God and is worshipped as God (Hagar names him ''Thou God seest me''; he speaks from the bush as the God of Abraham; Manoah fears he has seen God). Traditionally read as an appearance of the pre-incarnate Son.', 'Curated', 'Genesis 16:7', 'Genesis 16:7-13; Exodus 3:2-6; Judges 13:18-22', 17),
('christ_as_melchizedek', 'Christ as Melchizedek', 'god_the_son', 'Pre-incarnate appearance', NULL, 'Old Testament', true, 'Melchizedek, king of Salem and priest of the most high God, who blessed Abraham; ''without father, without mother... made like unto the Son of God; abideth a priest continually''. Read here as an appearance of the Son.', 'Curated', 'Genesis 14:18', 'Genesis 14:18-20; Psalms 110:4; Hebrews 7:1-3', 7),
('christ_wrestling_with_jacob', 'Christ wrestling with Jacob', 'god_the_son', 'Pre-incarnate appearance', NULL, 'Old Testament', false, 'The man who wrestled with Jacob at Peniel and blessed him; Jacob said ''I have seen God face to face''. Traditionally read as an appearance of the pre-incarnate Son.', 'Curated', 'Genesis 32:24', 'Genesis 32:24-30', 7),
('christ_as_captain_of_the_host', 'Christ as captain of the LORD''s host', 'god_the_son', 'Pre-incarnate appearance', NULL, 'Old Testament', false, 'The captain of the LORD''s host who appeared to Joshua with a drawn sword, accepted his worship and declared the ground holy. Traditionally read as an appearance of the pre-incarnate Son.', 'Curated', 'Joshua 5:13', 'Joshua 5:13-15', 3),
('christ_in_the_furnace', 'Christ in the fiery furnace', 'god_the_son', 'Pre-incarnate appearance', NULL, 'Old Testament', false, 'The fourth man in the furnace whose form was ''like the Son of God''. Traditionally read as an appearance of the pre-incarnate Son; Nebuchadnezzar calls him God''s angel.', 'Curated', 'Daniel 3:25', 'Daniel 3:24-28', 5),
('incarnation_of_the_son', 'Incarnation of the Son', 'god_the_son', 'Incarnation', NULL, 'New Testament', false, '''The Word was made flesh, and dwelt among us'': the Son born of Mary as Jesus of Nazareth, Emmanuel, God with us.', 'Curated', 'John 1:14', 'John 1:14; Matthew 1:23; Luke 2:7-11; Philippians 2:6-8', 10),
('risen_christ', 'Risen Christ', 'god_the_son', 'Resurrection appearance', NULL, 'New Testament', false, 'Jesus raised bodily from the dead, appearing over forty days to Mary Magdalene, the women, the disciples on the Emmaus road, Thomas, Peter, James and more than five hundred at once, before ascending from the Mount of Olives.', 'Curated', 'Matthew 28:9', 'Matthew 28:9-10; Matthew 28:16-20; Luke 24:13-51; John 20:11-29; John 21:1-23; Acts 1:3-9; 1 Corinthians 15:5-8', 99),
('exalted_christ', 'Exalted Christ', 'god_the_son', 'Exaltation', 'one like unto the Son of man; the Lamb', 'New Testament', false, 'The ascended Christ at the right hand of God: seen by Stephen standing at God''s right hand, revealed to Saul on the Damascus road, and seen by John as one like the Son of man among the lampstands and as the Lamb that was slain.', 'Curated', 'Acts 7:55', 'Acts 7:55-56; Acts 9:3-6; Revelation 1:13-18; Revelation 5:6', 13),
('voice_at_the_baptism', 'Voice from heaven at the baptism', 'god_the_father', 'Voice', NULL, 'New Testament', false, 'The Father''s voice at Jesus'' baptism: ''This is my beloved Son, in whom I am well pleased.''', 'Curated', 'Matthew 3:17', 'Matthew 3:17; Mark 1:11; Luke 3:22', 3),
('voice_at_the_transfiguration', 'Voice from the cloud at the transfiguration', 'god_the_father', 'Voice', NULL, 'New Testament', false, 'The Father''s voice from the bright cloud on the mount: ''This is my beloved Son, in whom I am well pleased; hear ye him.''', 'Curated', 'Matthew 17:5', 'Matthew 17:5; Mark 9:7; Luke 9:35; 2 Peter 1:17-18', 5),
('ancient_of_days', 'The Ancient of days', 'god_the_father', 'Vision', NULL, 'Old Testament', false, 'The Ancient of days seen enthroned in Daniel''s vision, with raiment white as snow, to whom one like the Son of man is brought and given dominion. Traditionally identified with the Father.', 'Curated', 'Daniel 7:9', 'Daniel 7:9-10; Daniel 7:13; Daniel 7:22', 4),
('pillar_of_cloud_and_fire', 'Pillar of cloud and of fire', 'god_1324', 'Visible sign', NULL, 'Old Testament', false, 'The LORD going before Israel by day in a pillar of cloud and by night in a pillar of fire, and standing between Israel and the Egyptians at the Red Sea.', 'Curated', 'Exodus 13:21', 'Exodus 13:21-22; Exodus 14:19-20; Exodus 14:24; Exodus 33:9-10', 7),
('fire_on_sinai', 'Fire and cloud on Mount Sinai', 'god_1324', 'Visible sign', NULL, 'Old Testament', false, 'The LORD descending on Mount Sinai in fire, smoke and thick cloud, with thunder and the sound of the trumpet, when he gave the Law.', 'Curated', 'Exodus 19:18', 'Exodus 19:16-20; Exodus 24:16-17', 7),
('spirit_as_a_dove', 'Spirit descending like a dove', 'holy_spirit_7400', 'Visible sign', NULL, 'New Testament', false, 'The Spirit of God descending like a dove and lighting on Jesus at his baptism, the sign by which John the Baptist knew him.', 'Curated', 'Matthew 3:16', 'Matthew 3:16; Mark 1:10; Luke 3:22; John 1:32-33', 5),
('tongues_of_fire', 'Cloven tongues of fire at Pentecost', 'holy_spirit_7400', 'Visible sign', NULL, 'New Testament', false, 'The rushing mighty wind and cloven tongues like as of fire that sat on each of the disciples at Pentecost, when they were all filled with the Holy Ghost.', 'Curated', 'Acts 2:3', 'Acts 2:1-4', 4);
